head.b:skin:

/* ==========================================================================
   VARIABLES, RESET, & BASE STYLES
   ========================================================================== */
:root {
    --primary-color: #ff4a57;
    --primary-dark: #e0323e;
    --secondary-color: #1a1a2e;
    --bg-color: #f8f9fa;
    --card-bg: #ffffff;
    --text-color: #2b2b2b;
    --text-muted: #6c757d;
    --border-color: #e9ecef;
    --max-width: 1200px;
    --font-sans: 'Inter', sans-serif;
    --transition: all 0.3s cubic-bezier(0.4, 0, 0.2, 1);
    --shadow: 0 4px 6px -1px rgba(0, 0, 0, 0.1), 0 2px 4px -1px rgba(0, 0, 0, 0.06);
    --shadow-lg: 0 10px 15px -3px rgba(0, 0, 0, 0.1), 0 4px 6px -2px rgba(0, 0, 0, 0.05);
}

* {
    box-sizing: border-box;
    margin: 0;
    padding: 0;
}

body {
    font-family: var(--font-sans);
    background-color: var(--bg-color);
    color: var(--text-color);
    line-height: 1.6;
    overflow-x: hidden;
}

a {
    color: inherit;
    text-decoration: none;
    transition: var(--transition);
}

img {
    max-width: 100%;
    height: auto;
}

/* Container Utility */
.container {
    width: 100%;
    max-width: var(--max-width);
    margin: 0 auto;
    padding: 0 24px;
}

.sr-only {
    position: absolute;
    width: 1px;
    height: 1px;
    padding: 0;
    margin: -1px;
    overflow: hidden;
    clip: rect(0, 0, 0, 0);
    white-space: nowrap;
    border: 0;
}

.skip-link {
    position: absolute;
    top: -100px;
    left: 20px;
    background: var(--primary-color);
    color: #ffffff;
    padding: 10px 20px;
    z-index: 9999;
    font-weight: 600;
    border-radius: 4px;
    transition: top 0.2s;
}
.skip-link:focus {
    top: 20px;
}

/* ==========================================================================
   MODERN NAVIGATION & HEADER (FLEXBOX)
   ========================================================================== */
.navbar {
    background-color: #ffffff;
    border-bottom: 1px solid var(--border-color);
    position: sticky;
    top: 0;
    z-index: 1000;
    padding: 16px 0;
}
.nav-container {
    display: flex;
    justify-content: space-between;
    align-items: center;
}
.logo {
    font-size: 24px;
    font-weight: 800;
    color: var(--secondary-color);
    letter-spacing: -0.5px;
}
.logo span {
    color: var(--primary-color);
}
.site-navigation {
    display: flex;
    align-items: center;
}
.nav-menu {
    display: flex;
    list-style: none;
    gap: 28px;
}
.nav-menu a {
    font-weight: 500;
    font-size: 15px;
    color: var(--secondary-color);
}
.nav-menu a:hover, .nav-menu a[aria-current="page"] {
    color: var(--primary-color);
}
.nav-right {
    display: flex;
    align-items: center;
    gap: 20px;
}
.search-box {
    display: flex;
    align-items: center;
    background-color: var(--bg-color);
    border: 1px solid var(--border-color);
    border-radius: 30px;
    padding: 6px 16px;
    gap: 10px;
}
.search-box svg {
    color: var(--text-muted);
    display: flex;
}
.search-box input {
    border: none;
    background: transparent;
    outline: none;
    font-size: 14px;
    color: var(--text-color);
    font-family: inherit;
}
.subscribe-btn {
    background-color: var(--primary-color);
    color: #ffffff;
    padding: 10px 24px;
    border-radius: 30px;
    font-weight: 600;
    font-size: 14px;
}
.subscribe-btn:hover {
    background-color: var(--primary-dark);
    transform: translateY(-1px);
}
.nav-toggle {
    display: none;
    background: none;
    border: none;
    cursor: pointer;
    flex-direction: column;
    gap: 6px;
    padding: 4px;
    z-index: 1001;
}
.nav-toggle-line {
    width: 24px;
    height: 2px;
    background-color: var(--secondary-color);
    transition: var(--transition);
}

/* Navbar Open State for Mobile */
.navbar.is-nav-open .nav-toggle .nav-toggle-line:nth-child(1) {
    transform: translateY(8px) rotate(45deg);
}
.navbar.is-nav-open .nav-toggle .nav-toggle-line:nth-child(2) {
    opacity: 0;
}
.navbar.is-nav-open .nav-toggle .nav-toggle-line:nth-child(3) {
    transform: translateY(-8px) rotate(-45deg);
}

/* ==========================================================================
   HERO & FEATURED SECTION (GRID & FLEXBOX)
   ========================================================================== */
.hero {
    padding: 80px 0;
    background-color: #ffffff;
    border-bottom: 1px solid var(--border-color);
}
.hero-grid {
    display: grid;
    grid-template-columns: 1.1fr 0.9fr;
    gap: 60px;
    align-items: center;
}
.hero-content {
    display: flex;
    flex-direction: column;
}
.hero-label {
    color: var(--primary-color);
    font-weight: 700;
    text-transform: uppercase;
    font-size: 13px;
    letter-spacing: 1.5px;
    margin-bottom: 16px;
}
.hero-title {
    font-size: 52px;
    font-weight: 800;
    line-height: 1.15;
    color: var(--secondary-color);
    letter-spacing: -1.5px;
    margin-bottom: 24px;
}
.hero-description {
    font-size: 18px;
    color: var(--text-muted);
    margin-bottom: 32px;
    max-width: 540px;
}
.hero-buttons {
    display: flex;
    gap: 16px;
    margin-bottom: 40px;
}
.btn {
    display: inline-block;
    padding: 14px 32px;
    border-radius: 30px;
    font-weight: 600;
    font-size: 15px;
    text-align: center;
}
.btn-primary {
    background-color: var(--primary-color);
    color: #ffffff;
}
.btn-primary:hover {
    background-color: var(--primary-dark);
    transform: translateY(-1.5px);
}
.btn-outline {
    border: 2px solid var(--border-color);
    color: var(--secondary-color);
}
.btn-outline:hover {
    background-color: var(--bg-color);
    border-color: var(--secondary-color);
    transform: translateY(-1.5px);
}
.hero-community {
    display: flex;
    align-items: center;
    gap: 16px;
}
.avatar-group {
    display: flex;
}
.avatar {
    width: 36px;
    height: 36px;
    border-radius: 50%;
    background-color: var(--secondary-color);
    color: #ffffff;
    display: flex;
    align-items: center;
    justify-content: center;
    font-weight: 700;
    font-size: 12px;
    border: 2px solid #ffffff;
    margin-left: -12px;
}
.avatar:first-child {
    margin-left: 0;
}
.hero-community p {
    font-size: 13px;
    color: var(--text-muted);
}

/* Featured Post Card */
.featured-post {
    background-color: var(--bg-color);
    border-radius: 20px;
    padding: 32px;
    border: 1px solid var(--border-color);
    display: flex;
    flex-direction: column;
    transition: var(--transition);
}
.featured-post:hover {
    transform: translateY(-4px);
    box-shadow: var(--shadow-lg);
}
.featured-image {
    height: 240px;
    background-color: #e2e8f0;
    border-radius: 14px;
    margin-bottom: 24px;
    position: relative;
    overflow: hidden;
}
.featured-overlay {
    position: absolute;
    top: 16px;
    left: 16px;
    background-color: var(--primary-color);
    color: #ffffff;
    padding: 4px 14px;
    border-radius: 20px;
    font-size: 12px;
    font-weight: 700;
    text-transform: uppercase;
}
.featured-post h2 {
    font-size: 24px;
    line-height: 1.3;
    margin-bottom: 12px;
    color: var(--secondary-color);
}
.featured-post p {
    color: var(--text-muted);
    font-size: 15px;
    margin-bottom: 24px;
}
.featured-meta {
    display: flex;
    gap: 16px;
    font-size: 13px;
    color: var(--text-muted);
    margin-bottom: 24px;
}

/* ==========================================================================
   UTILITY COMPONENTS & ZONES
   ========================================================================== */
/* Ad Zone */
.ad-zone {
    padding: 24px 0;
    background-color: #ffffff;
    border-bottom: 1px solid var(--border-color);
}
.ad-placeholder {
    text-align: center;
}
.ad-label {
    font-size: 11px;
    color: var(--text-muted);
    text-transform: uppercase;
    letter-spacing: 1.5px;
    display: block;
    margin-bottom: 10px;
}
.ad-box {
    background-color: var(--bg-color);
    border: 2px dashed var(--border-color);
    padding: 36px;
    font-size: 14px;
    color: var(--text-muted);
    border-radius: 12px;
    font-weight: 500;
}

/* Announcement Bar */
.announcement-bar {
    background-color: var(--secondary-color);
    color: #ffffff;
    padding: 12px 0;
    font-size: 14px;
}
.announcement-content {
    display: flex;
    align-items: center;
    justify-content: center;
    gap: 16px;
    flex-wrap: wrap;
}
.announcement-badge {
    background-color: var(--primary-color);
    padding: 3px 10px;
    border-radius: 6px;
    font-weight: 700;
    font-size: 11px;
    text-transform: uppercase;
}
.announcement-link {
    color: var(--primary-color);
    font-weight: 600;
    text-decoration: underline;
}

/* Quick Access Bar */
.quick-access {
    padding: 24px 0;
    background-color: var(--bg-color);
    border-bottom: 1px solid var(--border-color);
}
.quick-access-wrapper {
    display: flex;
    align-items: center;
    gap: 12px;
    flex-wrap: wrap;
}
.quick-title {
    font-size: 15px;
    font-weight: 700;
    color: var(--secondary-color);
    text-transform: uppercase;
    letter-spacing: 1px;
    margin-right: 12px;
}
.quick-pill {
    background-color: #ffffff;
    border: 1px solid var(--border-color);
    padding: 8px 18px;
    border-radius: 24px;
    font-size: 13px;
    font-weight: 600;
    color: var(--secondary-color);
}
.quick-pill:hover {
    background-color: var(--primary-color);
    color: #ffffff;
    border-color: var(--primary-color);
}

/* Publication Stats */
.stats {
    padding: 48px 0;
    background-color: #ffffff;
    border-bottom: 1px solid var(--border-color);
}
.stats-grid {
    display: grid;
    grid-template-columns: repeat(4, 1fr);
    gap: 24px;
}
.stat-card {
    text-align: center;
    padding: 16px;
}
.stat-card h2 {
    font-size: 42px;
    font-weight: 800;
    color: var(--primary-color);
    margin-bottom: 6px;
    letter-spacing: -1px;
}
.stat-card p {
    color: var(--text-muted);
    font-size: 14px;
    font-weight: 600;
    text-transform: uppercase;
    letter-spacing: 0.5px;
}

/* ==========================================================================
   SECTION WRAPPERS & GRIDS (GRID DESIGN SYSTEMS)
   ========================================================================== */
.section {
    padding: 80px 0;
}
.section-header {
    margin-bottom: 48px;
    max-width: 650px;
}
.section-header h2 {
    font-size: 36px;
    color: var(--secondary-color);
    letter-spacing: -1px;
    margin-bottom: 12px;
}
.section-header p {
    color: var(--text-muted);
    font-size: 16px;
}

/* Featured Categories Grid */
.category-grid {
    display: grid;
    grid-template-columns: repeat(3, 1fr);
    gap: 32px;
}
.category-card {
    background-color: #ffffff;
    padding: 36px;
    border-radius: 16px;
    border: 1px solid var(--border-color);
    display: flex;
    flex-direction: column;
    transition: var(--transition);
}
.category-card:hover {
    transform: translateY(-6px);
    box-shadow: var(--shadow-lg);
    border-color: rgba(255, 74, 87, 0.2);
}
.category-icon {
    background-color: var(--bg-color);
    color: var(--primary-color);
    width: 54px;
    height: 54px;
    border-radius: 12px;
    display: flex;
    align-items: center;
    justify-content: center;
    font-weight: 800;
    font-size: 14px;
    margin-bottom: 24px;
    border: 1px solid var(--border-color);
}
.category-card h3 {
    font-size: 20px;
    color: var(--secondary-color);
    margin-bottom: 12px;
}
.category-card p {
    color: var(--text-muted);
    font-size: 15px;
    margin-bottom: 24px;
    flex-grow: 1;
}
.category-link {
    font-weight: 700;
    color: var(--primary-color);
    font-size: 14px;
    text-transform: uppercase;
    letter-spacing: 0.5px;
}

/* Featured Story Section (Split Grid Layout) */
.featured-story {
    background-color: var(--bg-color);
}
.featured-story-grid {
    display: grid;
    grid-template-columns: 1fr 1fr;
    gap: 60px;
    align-items: center;
}
.featured-story-image {
    height: 400px;
    background-color: #e2e8f0;
    border-radius: 20px;
    position: relative;
    overflow: hidden;
}
.story-badge {
    position: absolute;
    top: 24px;
    left: 24px;
    background-color: var(--primary-color);
    color: #ffffff;
    padding: 6px 16px;
    border-radius: 24px;
    font-weight: 700;
    font-size: 12px;
    text-transform: uppercase;
    letter-spacing: 0.5px;
}
.story-category {
    color: var(--primary-color);
    font-weight: 700;
    text-transform: uppercase;
    font-size: 13px;
    letter-spacing: 1px;
    margin-bottom: 16px;
}
.featured-story-content h2 {
    font-size: 40px;
    color: var(--secondary-color);
    margin-bottom: 20px;
    line-height: 1.2;
    letter-spacing: -1px;
}
.featured-story-content p {
    color: var(--text-muted);
    margin-bottom: 28px;
    font-size: 16px;
    line-height: 1.7;
}
.story-meta {
    display: flex;
    gap: 24px;
    font-size: 14px;
    color: var(--text-muted);
    margin-bottom: 32px;
}

/* Editors Picks Grid */
.editors-picks {
    background-color: #ffffff;
}
.editors-picks .section-header {
    display: flex;
    justify-content: space-between;
    align-items: flex-end;
    max-width: none;
}
.section-label {
    color: var(--primary-color);
    font-weight: 700;
    text-transform: uppercase;
    font-size: 13px;
    letter-spacing: 1px;
    margin-bottom: 8px;
}
.editor-grid {
    display: grid;
    grid-template-columns: repeat(3, 1fr);
    gap: 32px;
}
.editor-card {
    display: flex;
    gap: 24px;
    padding: 24px;
    border-radius: 16px;
    border: 1px solid var(--border-color);
    transition: var(--transition);
}
.editor-card:hover {
    transform: translateY(-4px);
    box-shadow: var(--shadow);
}
.editor-number {
    font-size: 36px;
    font-weight: 800;
    color: var(--border-color);
    line-height: 1;
}
.editor-category {
    color: var(--primary-color);
    font-weight: 700;
    font-size: 11px;
    text-transform: uppercase;
    margin-bottom: 6px;
    letter-spacing: 0.5px;
}
.editor-card h3 {
    font-size: 18px;
    margin-bottom: 10px;
    line-height: 1.4;
    color: var(--secondary-color);
}
.editor-card p {
    font-size: 14px;
    color: var(--text-muted);
}

/* Latest Articles Grid */
.flex-between {
    display: flex;
    justify-content: space-between;
    align-items: center;
}
.mb-5 {
    margin-bottom: 40px;
}
.article-grid {
    display: grid;
    grid-template-columns: repeat(3, 1fr);
    gap: 32px;
}
.article-card {
    background-color: #ffffff;
    border-radius: 16px;
    border: 1px solid var(--border-color);
    overflow: hidden;
    transition: var(--transition);
    display: flex;
    flex-direction: column;
}
.article-card:hover {
    transform: translateY(-6px);
    box-shadow: var(--shadow-lg);
}
.article-image {
    height: 220px;
    background-color: #e2e8f0;
    position: relative;
}
.article-badge {
    position: absolute;
    top: 16px;
    left: 16px;
    background-color: var(--primary-color);
    color: #ffffff;
    padding: 4px 12px;
    border-radius: 20px;
    font-size: 11px;
    font-weight: 700;
    text-transform: uppercase;
}
.article-content {
    padding: 28px;
    display: flex;
    flex-direction: column;
    flex-grow: 1;
}
.article-meta {
    display: flex;
    gap: 16px;
    font-size: 12px;
    color: var(--text-muted);
    margin-bottom: 12px;
}
.article-card h3 {
    font-size: 20px;
    margin-bottom: 12px;
    line-height: 1.4;
    color: var(--secondary-color);
}
.article-card p {
    font-size: 14px;
    color: var(--text-muted);
    margin-bottom: 24px;
    line-height: 1.6;
    flex-grow: 1;
}
.article-link {
    color: var(--primary-color);
    font-weight: 700;
    font-size: 14px;
    text-transform: uppercase;
    letter-spacing: 0.5px;
}

/* ==========================================================================
   DYNAMIC BLOGGER WRAPPER STYLES
   ========================================================================== */
.blog-posts {
    display: grid;
    grid-template-columns: repeat(2, 1fr);
    gap: 32px;
}
.post-outer {
    background: #ffffff;
    border: 1px solid var(--border-color);
    border-radius: 16px;
    overflow: hidden;
    transition: var(--transition);
}
.post-outer:hover {
    transform: translateY(-5px);
    box-shadow: var(--shadow-lg);
}

/* ==========================================================================
   NEWSLETTER BOX
   ========================================================================== */
.newsletter {
    background-color: var(--secondary-color);
    color: #ffffff;
    padding: 96px 0;
}
.newsletter-box {
    text-align: center;
    max-width: 640px;
    margin: 0 auto;
}
.newsletter-box h2 {
    font-size: 38px;
    font-weight: 800;
    letter-spacing: -1px;
    margin-bottom: 16px;
}
.newsletter-text {
    font-size: 16px;
    margin-bottom: 36px;
    color: rgba(255, 255, 255, 0.8);
}
.newsletter-form {
    display: flex;
    gap: 16px;
}
.newsletter-input {
    flex-grow: 1;
    padding: 16px 28px;
    border-radius: 30px;
    border: 1px solid rgba(255,255,255,0.1);
    outline: none;
    font-size: 15px;
    font-family: inherit;
    background: rgba(255, 255, 255, 0.05);
    color: white;
    transition: var(--transition);
}
.newsletter-input:focus {
    border-color: var(--primary-color);
    background: rgba(255, 255, 255, 0.1);
}

/* ==========================================================================
   FOOTER (GRID & FLEXBOX SYSTEM)
   ========================================================================== */
.site-footer {
    background-color: #0d0d1a;
    color: rgba(255, 255, 255, 0.7);
    padding: 80px 0 40px;
}
.footer-container {
    max-width: var(--max-width);
    margin: 0 auto;
    padding: 0 24px;
}
.footer-top {
    display: grid;
    grid-template-columns: 0.9fr 1.1fr;
    gap: 64px;
    margin-bottom: 48px;
}
.footer-brand {
    display: flex;
    flex-direction: column;
}
.footer-logo {
    font-size: 28px;
    font-weight: 800;
    color: #ffffff;
    display: inline-block;
    margin-bottom: 16px;
}
.footer-logo span {
    color: var(--primary-color);
}
.footer-description {
    margin-bottom: 16px;
    font-size: 15px;
    line-height: 1.6;
}
.footer-tagline {
    font-size: 13px;
    line-height: 1.5;
    color: rgba(255, 255, 255, 0.45);
}
.footer-navigation {
    display: grid;
    grid-template-columns: repeat(3, 1fr);
    gap: 32px;
}
.footer-title {
    color: #ffffff;
    font-size: 15px;
    font-weight: 700;
    margin-bottom: 24px;
    text-transform: uppercase;
    letter-spacing: 1px;
}
.footer-links {
    list-style: none;
}
.footer-links li {
    margin-bottom: 14px;
}
.footer-links a {
    font-size: 14px;
}
.footer-links a:hover {
    color: var(--primary-color);
}
.footer-social {
    display: flex;
    flex-direction: column;
    gap: 12px;
}
.footer-social a {
    font-size: 14px;
}
.footer-social a:hover {
    color: var(--primary-color);
}
.footer-divider {
    border: none;
    border-top: 1px solid rgba(255, 255, 255, 0.08);
    margin-bottom: 40px;
}
.footer-bottom {
    display: flex;
    justify-content: space-between;
    font-size: 14px;
    align-items: center;
}
.footer-copyright strong {
    color: #ffffff;
}
.footer-credit a {
    color: #ffffff;
    font-weight: 600;
}
.footer-credit a:hover {
    color: var(--primary-color);
}

/* ==========================================================================
   RESPONSIVE GRID ADAPTIONS (MEDIA QUERIES)
   ========================================================================== */
@media (max-width: 1024px) {
    .hero-grid {
        gap: 40px;
    }
    .hero-title {
        font-size: 42px;
    }
    .category-grid, .editor-grid, .article-grid {
        gap: 24px;
    }
}

@media (max-width: 900px) {
    .hero-grid, .featured-story-grid, .footer-top {
        grid-template-columns: 1fr;
        gap: 48px;
    }
    .stats-grid {
        grid-template-columns: repeat(2, 1fr);
    }
    .category-grid, .editor-grid, .article-grid {
        grid-template-columns: repeat(2, 1fr);
    }
    .footer-navigation {
        grid-template-columns: repeat(3, 1fr);
        gap: 20px;
    }
}

@media (max-width: 768px) {
    .navbar {
        padding: 12px 0;
    }
    .nav-toggle {
        display: flex;
    }
    .site-navigation {
        display: none;
    }
    /* Mobile Navigation Overrides */
    .navbar.is-nav-open .site-navigation {
        display: block;
        position: absolute;
        top: 100%;
        left: 0;
        width: 100%;
        background-color: #ffffff;
        padding: 30px 24px;
        border-bottom: 1px solid var(--border-color);
        box-shadow: var(--shadow-lg);
    }
    .navbar.is-nav-open .nav-menu {
        flex-direction: column;
        gap: 20px;
    }
    .navbar.is-nav-open .nav-menu a {
        font-size: 18px;
        display: block;
    }
    .nav-right .search-box, .nav-right .subscribe-btn {
        display: none; /* Can add inside nav overlay for small devices */
    }

    .category-grid, .editor-grid, .article-grid, .footer-navigation, .stats-grid {
        grid-template-columns: 1fr;
        gap: 24px;
    }
    .hero-title {
        font-size: 36px;
    }
    .newsletter-form {
        flex-direction: column;
        gap: 12px;
    }
    .newsletter-input {
        width: 100%;
    }
    .footer-bottom {
        flex-direction: column;
        gap: 16px;
        text-align: center;
    }
}

body.script:
//
(function () {
    var navbar = document.querySelector('.navbar');
    var toggle = document.querySelector('.nav-toggle');
    var navigation = document.getElementById('primary-navigation');

    if (!navbar || !toggle || !navigation) {
        return;
    }

    function setMenuState(isOpen) {
        navbar.classList.toggle('is-nav-open', isOpen);
        toggle.setAttribute('aria-expanded', String(isOpen));
        toggle.setAttribute('aria-label', isOpen ? 'Close navigation menu' : 'Open navigation menu');
    }

    toggle.addEventListener('click', function () {
        setMenuState(toggle.getAttribute('aria-expanded') !== 'true');
    });

    navigation.addEventListener('click', function (event) {
        if (event.target.closest('a')) {
            setMenuState(false);
        }
    });

    document.addEventListener('click', function (event) {
        if (!navbar.contains(event.target)) {
            setMenuState(false);
        }
    });

    document.addEventListener('keydown', function (event) {
        if (event.key === 'Escape') {
            setMenuState(false);
            toggle.focus();
        }
    });

    window.addEventListener('resize', function () {
        if (window.matchMedia('(min-width: 901px)').matches) {
            setMenuState(false);
        }
    });
}());
//
